package com.tencent.weknora.knowledge;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.tencent.weknora.task.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** One atomic durable handoff owns both summary and question terminal slots. */
public final class QuestionGenerationFanout {
  public record Plan(boolean current,boolean summary,boolean questionEnabled,int questionBatches,int questionChunks,int textChunks,int plannedGraph,int enqueuedGraph,boolean enqueuedAutoTag,boolean completed){public Plan(boolean current,boolean summary,boolean questionEnabled,int questionBatches,int questionChunks,int textChunks,int plannedGraph,int enqueuedGraph){this(current,summary,questionEnabled,questionBatches,questionChunks,textChunks,plannedGraph,enqueuedGraph,false,false);}public Plan(boolean current,boolean summary,boolean questionEnabled,int questionBatches,int questionChunks,int textChunks){this(current,summary,questionEnabled,questionBatches,questionChunks,textChunks,0,0);}public int total(){return (summary?1:0)+questionBatches+enqueuedGraph;}}
  private final JdbcTemplate jdbc;private final ObjectMapper json;private final QuestionGenerationRepository repository;private final KnowledgeFileUpload.Enqueuer tasks;private final TransactionTemplate tx;private final Clock clock;private final boolean postgres;private final KnowledgeProcessingSpanTracker tracker;private final GraphExtractionFanout graph;private final KnowledgeAutoTagHandler autoTag;
  public QuestionGenerationFanout(JdbcTemplate jdbc,ObjectMapper json,QuestionGenerationRepository repository,KnowledgeFileUpload.Enqueuer tasks,PlatformTransactionManager manager,Clock clock,KnowledgeProcessingSpanTracker tracker){this(jdbc,json,repository,tasks,manager,clock,tracker,null);}
  public QuestionGenerationFanout(JdbcTemplate jdbc,ObjectMapper json,QuestionGenerationRepository repository,KnowledgeFileUpload.Enqueuer tasks,PlatformTransactionManager manager,Clock clock,KnowledgeProcessingSpanTracker tracker,GraphExtractionFanout graph){this(jdbc,json,repository,tasks,manager,clock,tracker,graph,null);}
  public QuestionGenerationFanout(JdbcTemplate jdbc,ObjectMapper json,QuestionGenerationRepository repository,KnowledgeFileUpload.Enqueuer tasks,PlatformTransactionManager manager,Clock clock,KnowledgeProcessingSpanTracker tracker,GraphExtractionFanout graph,KnowledgeAutoTagHandler autoTag){this.autoTag=autoTag;this.graph=graph;this.tracker=tracker;this.jdbc=jdbc;this.json=json;this.repository=repository;this.tasks=tasks;this.tx=new TransactionTemplate(manager);this.clock=clock;postgres=Boolean.TRUE.equals(jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Boolean>)c->c.getMetaData().getDatabaseProductName().equals("PostgreSQL")));}
  public Plan handoff(TaskRecord job,DocumentProcessingRepository.Snapshot original,JsonNode effective)throws TaskFailure {
    Integer invalid=jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE tenant_id=? AND knowledge_id=? AND deleted_at IS NULL AND chunk_type IN ('text','image_ocr','image_caption') AND knowledge_base_id<>?",Integer.class,job.tenantId(),job.payload().path("knowledge_id").asText(),job.payload().path("knowledge_base_id").asText());if(invalid!=null&&invalid>0)throw new TaskFailure("postprocess chunk binding changed",false);
    var loaded=repository.load(job);if(loaded.isEmpty()||repository.superseded(job))return new Plan(false,false,false,0,0,0);var snapshot=loaded.get();for(String field:List.of("file_path","file_hash","file_name","file_type"))if(!original.knowledge().path(field).equals(snapshot.knowledge().path(field)))return new Plan(false,false,false,0,0,0);
    var textLike=snapshot.all().stream().filter(c->Set.of("text","image_ocr","image_caption").contains(c.path("chunk_type").asText())).toList();boolean summary=effective.path("summary_enabled").asBoolean()&&!textLike.isEmpty();JsonNode strategy=snapshot.knowledgeBase().path("indexing_strategy");boolean question=effective.path("question_generation_config").path("enabled").asBoolean()&&(strategy.path("vector_enabled").asBoolean()||strategy.path("keyword_enabled").asBoolean());
    var chunks=question?snapshot.text().stream().filter(c->QuestionGenerationText.extractable(c.path("content").asText())).sorted(Comparator.comparingLong(c->c.path("start_at").asLong())).toList():List.<ObjectNode>of();int batches=(chunks.size()+19)/20;var graphChunks=graph!=null&&effective.path("graph_enabled").asBoolean()?graph.select(textLike):List.<ObjectNode>of();var plan=new Plan(true,summary,question&&!textLike.isEmpty(),batches,chunks.size(),textLike.size(),graphChunks.size(),graph!=null&&graph.enabled()?graphChunks.size():0);
    return tx.execute(s->{repository.check(job);for(var chunk:java.util.stream.Stream.concat(chunks.stream(),graphChunks.stream()).toList())if(!repository.current(job,snapshot,chunk))return new Plan(false,false,false,0,0,0);
      if(plan.total()==0){int done=jdbc.update("UPDATE knowledges SET parse_status='completed',summary_status='none',pending_subtasks_count=0,error_message='',processed_at=?,updated_at=? WHERE tenant_id=? AND id=? AND knowledge_base_id=? AND deleted_at IS NULL AND parse_status='processing'",postgres?java.sql.Timestamp.from(clock.instant()):GoSqliteTimestamp.write(clock.instant()),postgres?java.sql.Timestamp.from(clock.instant()):GoSqliteTimestamp.write(clock.instant()),job.tenantId(),snapshot.knowledge().path("id").asText(),snapshot.knowledgeBase().path("id").asText());if(done==0)return new Plan(false,false,false,0,0,0);boolean tagged=autoTag!=null&&autoTag.enqueue(job,original,plan.textChunks());repository.check(job);return new Plan(plan.current(),plan.summary(),plan.questionEnabled(),plan.questionBatches(),plan.questionChunks(),plan.textChunks(),plan.plannedGraph(),plan.enqueuedGraph(),tagged,true);}
      int changed=jdbc.update("UPDATE knowledges SET parse_status='finalizing',summary_status=CASE WHEN ? THEN 'pending' ELSE summary_status END,pending_subtasks_count=?,error_message='',updated_at=? WHERE tenant_id=? AND id=? AND knowledge_base_id=? AND deleted_at IS NULL AND parse_status='processing'",summary,plan.total(),postgres?java.sql.Timestamp.from(clock.instant()):GoSqliteTimestamp.write(clock.instant()),job.tenantId(),snapshot.knowledge().path("id").asText(),snapshot.knowledgeBase().path("id").asText());if(changed==0)return new Plan(false,false,false,0,0,0);boolean tagged=autoTag!=null&&autoTag.enqueue(job,original,plan.textChunks());
      if(summary)enqueue(job,"summary:generation",payload(job),"summary");
      group(job,plan);int count=QuestionGenerationText.count(effective.path("question_generation_config").path("question_count").asInt());for(int start=0;start<chunks.size();start+=20){int end=Math.min(start+20,chunks.size());ObjectNode payload=payload(job);payload.remove(List.of("chunk_id","chunk_ids","prev_chunk_id","next_chunk_id","refresh"));payload.put("question_count",count);if(start>0)payload.put("batch_index",start/20);var ids=payload.putArray("chunk_ids");for(int i=start;i<end;i++)ids.add(chunks.get(i).path("id").asText());if(start>0)payload.put("prev_chunk_id",chunks.get(start-1).path("id").asText());if(end<chunks.size())payload.put("next_chunk_id",chunks.get(end).path("id").asText());enqueue(job,"question:generation",payload,"question");}if(graph!=null&&graph.enabled())for(int i=0;i<graphChunks.size();i++)graph.enqueue(job,snapshot.knowledgeBase(),graphChunks.get(i),i);repository.check(job);return new Plan(plan.current(),plan.summary(),plan.questionEnabled(),plan.questionBatches(),plan.questionChunks(),plan.textChunks(),plan.plannedGraph(),plan.enqueuedGraph(),tagged,false);});
  }
  public boolean graphSupported(){return graph!=null;}
  void group(TaskRecord job,Plan plan){if(!plan.questionEnabled()||tracker==null)return;long attempt=job.payload().path("attempt").asLong();var parent=tracker.lookupStage(job.tenantId(),job.payload().path("knowledge_id").asText(),attempt,"postprocess");var group=tracker.beginSubspan(parent,"postprocess.question","subspan",json.createObjectNode().put("batch_count",plan.questionBatches()).put("chunk_count",plan.questionChunks()).put("batch_size",20));tracker.end(group,json.createObjectNode().put("batch_count",plan.questionBatches()).put("chunk_count",plan.questionChunks()));}
  private ObjectNode payload(TaskRecord job){var p=json.createObjectNode();for(String key:List.of("tenant_id","knowledge_base_id","knowledge_id"))p.set(key,job.payload().path(key));for(String key:List.of("language","lf_trace_id","lf_parent_obs_id","lf_traceparent","lf_user_id","lf_session_id"))if(!job.payload().path(key).asText().isEmpty())p.set(key,job.payload().get(key));if(job.payload().path("attempt").asLong()>0)p.put("attempt",job.payload().path("attempt").asLong());return p;}
  private void enqueue(TaskRecord job,String type,ObjectNode payload,String queue){try{tasks.enqueue(job.tenantId(),type,payload,new KnowledgeFileUpload.TaskOptions(queue,3,Duration.ofMinutes(30)));}catch(Exception e){throw new IllegalStateException("enrichment handoff enqueue failed",e);}}
}
